<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileWebsiteUrlAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileWebsiteUrlAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileWebsiteUrlAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getWebsiteUrl returns null on a freshly created holder.
     */
    public function testWebsiteUrlNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileWebsiteUrlAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isWebsiteUrlAssigned());
        $this->assertNull($holder->getWebsiteUrl());
    }
}
class ImplWithUserProfileWebsiteUrlAttributeHolderUnitTest
{
    use UserProfileWebsiteUrlAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWebsiteUrlRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWebsiteUrl();
    }
}
